import numpy as np
def equation(t, P, params):
    c0,c1,c2,c3,c4=params[0],params[1],params[2],params[3],params[4]
    return c0*np.sin(c0*np.sqrt(t)) + c1*P*t**c2 + c3*P*(1-P/c4)
